import json, glob, os
out=open('/sdcard/wikillm/07_user_messages_omnirush.md','w')
n=0
files = glob.glob(os.path.expanduser('~/.omnirush/omnirush-turns/*/*.json')) + glob.glob(os.path.expanduser('~/.omnirush/omnirush-archive/baselines/*.json'))
def walk(o):
    global n
    if isinstance(o,dict):
        role=o.get('role')
        if role=='user':
            c=o.get('content') or o.get('text') or o.get('message')
            if isinstance(c,list):
                c=' '.join(x.get('text','') for x in c if isinstance(x,dict))
            if isinstance(c,str) and c.strip() and not c.startswith(('<tool_result','system')):
                n+=1
                out.write(f"\n\n===== USER #{n} =====\n{c[:4000]}\n")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
for f in files:
    try: d=json.load(open(f))
    except Exception as e: continue
    out.write(f"\n\n########## SOURCE: {f} ##########\n")
    walk(d)
out.close()
print('files:',len(files),'extracted:',n)
EOF
